# -*- coding: utf-8 -*-
"""
sistema_simple.py  -  BioAccess completo en UNA sola PC (archivo unico e independiente)

QUE ES ESTE ARCHIVO
-------------------
Este archivo es el SIMULADOR PORTATIL de BioAccess: permite abrir y
demostrar el sistema completo (terminal PC + movil) en una unica computadora,
sin telefono, sin camara y sin huella real.

QUE NO ES
---------
No es la aplicacion Android, ni el instalador, ni una version distinta de
BioAccess. Los archivos que se ejecutan aqui son una COPIA EXACTA del sistema
original: bioaccess.py, bioaccess_server.py y mobile/ (index.html,
app.css y app.js). Por eso la apariencia y el flujo son identicos al sistema
real.

COMO FUNCIONA (de arriba hacia abajo)
-------------------------------------
1) _ensure_deps() revisa las dependencias de Python. Si falta algo,
   lo instala con pip automaticamente. Esto permite copiar el archivo a
   otra PC y abrirlo con F5 sin preparar nada antes.

2) _BUNDLE guarda dentro de este .py los 5 archivos reales codificados en
   base64. Base64 se usa porque permite guardar texto (con tildes, saltos de
   linea o comillas) dentro de un literal de Python de forma segura.

3) Al ejecutarse, el programa "abre la maleta": escribe esos 5 archivos en
   una carpeta temporal (%TEMP%/bioaccess_simple_bundle). Antes de usar el
   base64 busca una copia local junto a este archivo; si existe
   (bioaccess.py, bioaccess_server.py o mobile/...), usa ESA copia. Esto
   facilita editar y mostrar el codigo durante una exposicion.

4) sys.path.insert() le dice a Python que busque bioaccess dentro de esa
   carpeta temporal. Despues importa el sistema real extraido.

5) main() crea tres ventanas:
   - Terminal PC: el SuperCustomBio real de bioaccess.py.
   - Celular simulado: QWebEngineView con el index.html real de mobile/.
   - AYUDA SIMULADOR: ventana auxiliar que NO pertenece a BioAccess; solo
     existe para enlazar (vincular) el celular simulado con la PC sin usar
     QR ni camara.

POR QUE ESTA HECHO ASI
----------------------
- Un solo archivo: se puede copiar a cualquier PC y ejecutarse sin el repo.
- Carpeta temporal: import y el servidor (StaticFiles) necesitan rutas reales.
- Copia local con prioridad: permite ensenar o modificar el codigo abierto
  sin regenerar el _BUNDLE durante la clase.
- _BUNDLE base64: garantiza que el archivo siga siendo independiente.
- Ventana auxiliar: separa claramente lo que es simulador de lo que es
  BioAccess real.

USO
---
  - En Spyder: abrir este archivo y pulsar Run (F5).
  - En consola: python sistema_simple.py

NOTA IMPORTANTE
---------------
Si modificas las copias abiertas (bioaccess.py, mobile/, etc.) solo cambia
el simulador en esta carpeta. Para publicar cambios dentro del .py hay que
regenerar _BUNDLE con regen_bundle.py (ver COMO_FUNCIONA.md).
"""
import sys, os, base64, tempfile, subprocess

# --- 1) Auto-instalacion de dependencias ---
# Que es: la lista minima de paquetes que BioAccess necesita para arrancar.
# Como funciona: se usa primero para saber que debe importarse; si falta,
# se instala con pip.
# Por que esta asi: asi este archivo puede llevarse a otra PC sin preparar
# el entorno manualmente antes de abrirlo.
_REQUIRED = ["PyQt6", "PyQt6-WebEngine", "fastapi", "uvicorn[standard]",
             "websockets", "qrcode"]

def _ensure_deps():
    # modmap traduce el nombre del paquete de pip al nombre que se importa
    # en Python. Ejemplo: PyQt6-WebEngine se instala con pip, pero se importa
    # como PyQt6.QtWebEngineWidgets.
    modmap = {"pyqt6": "PyQt6", "pyqt6_webengine": "PyQt6.QtWebEngineWidgets",
              "fastapi": "fastapi", "uvicorn": "uvicorn",
              "websockets": "websockets", "qrcode": "qrcode"}
    for pkg in _REQUIRED:
        mod = pkg.split("[")[0].replace("-", "_").lower()
        import_name = modmap.get(mod, mod)
        try:
            __import__(import_name.split(".")[0])
        except ImportError:
            print("[auto-install] instalando " + pkg + " ...")
            subprocess.check_call([sys.executable, "-m", "pip", "install", pkg,
                                  "--quiet", "--disable-pip-version-check"])

# Se ejecuta al cargar el archivo: sin esto, un PC con Python vacio fallaria
# antes de poder crear las ventanas o importar bioaccess.
_ensure_deps()

# --- 2) Bundle embebido (los archivos reales guardados dentro de este .py) ---
# Que es: un diccionario {ruta relativa -> contenido codificado en base64}.
#
# Los 5 archivos son exactamente los del BioAccess real:
#   - bioaccess.py          Terminal PC y logica principal
#   - bioaccess_server.py   Servidor de emparejamiento, eventos y WebSocket
#   - mobile/index.html     Estructura del celular
#   - mobile/app.css        Estilos del celular
#   - mobile/app.js         Logica del celular
#
# COMO FUNCIONA:
#   base64 no comprime; traduce bytes a texto seguro (A-Z, a-z, 0-9, +, /).
#   Al extraer, b64decode convierte esas letras otra vez en el archivo real.
#
# POR QUE ESTA ASI:
#   - Un .py no puede "adjuntar" archivos como un .zip externo.
#   - Guardar los archivos pegotes en triple comillas romperia el archivo
#     por tildes, comillas y saltos de linea.
#   - Base64 permite meter TODO dentro de una unica variable.
#
# QUE PASA SI SE CAMBIA:
#   - Editar las copias abiertas NO modifica este bloque: el simulador usara
#     archivos distintos a los que van incrustados.
#   - Para cambiar lo que viaja dentro de este .py hay que regenerar _BUNDLE
#     con regen_bundle.py (ver COMO_FUNCIONA.md).
_BUNDLE = {
    'bioaccess.py': "",
    'bioaccess_server.py': "",
    'mobile/index.html': "",
    'mobile/app.css': "",
    'mobile/app.js': "",
}

# --- 3) Extraer el sistema a una carpeta temporal ---
# Que es: la carpeta donde el programa "saca de la maleta" los 5 archivos
# para poder importarlos como codigo Python y servir el movil por HTTP.
#
# Como funciona:
#   - %TEMP%/bioaccess_simple_bundle es escrita CADA VEZ que corre. Eso
#     evita archivos viejos y permite que cambios locales se copien ahi.
#   - Si existe una copia junto a este archivo (_HERE), se usa ESA.
#   - Si no existe, se decodifica desde _BUNDLE base64.
#
# Por que esta asi:
#   - import bioaccess necesita un archivo .py real en disco.
#   - StaticFiles (servidor) necesita una carpeta mobile/ real con rutas.
#   - La copia local permite ensenar sin tocar las cadenas base64.
#
# QUE NO SE DEBE HACER:
#   - No modificar los archivos DENTRO de TEMP esperando que sean permanentes:
#     se sobrescriben en el siguiente arranque.
_EXTRACT_DIR = os.path.join(tempfile.gettempdir(), "bioaccess_simple_bundle")
os.makedirs(_EXTRACT_DIR, exist_ok=True)

# _HERE apunta a la carpeta donde vive ESTE archivo. Sirve para encontrar
# las copias abiertas (bioaccess.py, bioaccess_server.py, mobile/*).
_HERE = os.path.dirname(os.path.abspath(__file__))

for rel, data in _BUNDLE.items():
    dst = os.path.join(_EXTRACT_DIR, rel.replace("/", os.sep))
    os.makedirs(os.path.dirname(dst), exist_ok=True)
    local = os.path.join(_HERE, rel.replace("/", os.sep))
    if os.path.exists(local):
        # Prioridad: copia local junto al archivo. Facilita editar y exponer.
        with open(local, "rb") as fin, open(dst, "wb") as fout:
            fout.write(fin.read())
    else:
        # Respaldo: extraer del base64 incrustado. Permite que el .py solo
        # siga funcionando en cualquier PC.
        with open(dst, "wb") as f:
            f.write(base64.b64decode(data))

# Se agrega la carpeta extraida al principio de la busqueda de modulos.
# Debe hacerse ANTES del import bioaccess; si no, Python podria tomar otro
# bioaccess.py de otro lado o fallar al no encontrar el servidor/modulos.
if _EXTRACT_DIR not in sys.path:
    sys.path.insert(0, _EXTRACT_DIR)

# --- 4) Importar y usar el sistema REAL extraido ---
# Que es: carga el Terminal PC dentro de esta misma aplicacion.
# Por que asi: asi no hay una "reconstruccion parecida"; se usa bioaccess.py
# tal cual, con SuperCustomBio() y su servidor embebido.
import bioaccess
import json
import urllib.request
import urllib.parse
# Estos imports son solo lo necesario para la ventana auxiliar y el celular.
from PyQt6.QtWidgets import QApplication, QMainWindow, QWidget, QVBoxLayout, QLabel, QPushButton
from PyQt6.QtCore import QUrl, QTimer
from PyQt6.QtWebEngineWidgets import QWebEngineView

def main():
    # Punto de entrada. Que hace:
    #   1) crea la aplicacion Qt,
    #   2) abre el Terminal PC real,
    #   3) abre el celular simulado,
    #   4) abre la ventana auxiliar para vincular,
    #   5) queda a la espera de cerrar la PC.
    app = QApplication(sys.argv)
    app.setApplicationName("BioAccess Simulador")

    # Ventana 1: Terminal PC. Es el mismo SuperCustomBio() del proyecto.
    # Al crearlo, bioaccess.py arranca su servidor embebido (PUERTO 8080
    # o siguiente libre) y queda escuchando peticiones de la APK/movil.
    pc = bioaccess.SuperCustomBio()
    pc.setWindowTitle("BioAccess - Terminal PC (simulador)")
    pc.show()

    # Se detecta el puerto real usado por el servidor. Se usa base para:
    #   - apuntar el movil al mismo servidor;
    #   - llamar /api/pair/verify desde la ventana auxiliar.
    port = getattr(pc, "server_port", 8080) or 8080
    base = "http://127.0.0.1:%d" % port

    # Ventana 2: celular simulado. Es una pagina real servida por el
    # servidor en /mobile/index.html, mostrada dentro de QtWebEngine.
    # Por eso se ve el mismo frontend que tendria la APK.
    mob = QMainWindow()
    mob.setWindowTitle("BioAccess Mobile (simulador PC)")
    mob.resize(420, 780)
    view = QWebEngineView()
    mob.setCentralWidget(view)

    #---------------- Ventana 3: AYUDA SIMULADOR ----------------
    # NO es parte de BioAccess. Existe porque en desktop no hay camara (QR)
    # ni huella BiometricPrompt como en un telefono. El flujo de vinculacion
    # sigue siendo el normal: codigo -> /api/pair/verify -> ACEPTAR en la PC.
    helper = QMainWindow()
    helper.setWindowTitle("// AYUDA SIMULADOR (no es BioAccess)")
    helper.setFixedSize(390, 250)
    hw = QWidget()
    hw.setStyleSheet("background:#050b18; color:#b8e4ff; font-family:Consolas,monospace;")
    lay = QVBoxLayout(hw)
    lay.setContentsMargins(14, 12, 14, 12)
    lay.setSpacing(8)
    titulo = QLabel("// SIMULADOR - VINCULACION EXPRESS")
    titulo.setStyleSheet("color:#22d3ff; font-size:13px; font-weight:bold; letter-spacing:2px;")
    lay.addWidget(titulo)
    info = QLabel(
        "El movil del simulador usa el mismo codigo que la APK.\n"
        "Para que la PC le pida la huella debe vincularse UNA vez:\n"
        "1) Pulsa VINCULAR.  2) En la PC pulsa ACEPTAR."
    )
    info.setWordWrap(True)
    info.setStyleSheet("color:#8fb8d8; font-size:11px; line-height:150%;")
    lay.addWidget(info)
    btn = QPushButton("1)  VINCULAR CELULAR (1 CLIC)")
    btn.setFixedHeight(38)
    btn.setStyleSheet(
        "QPushButton{background:#0b2a3a; border:1px solid #22d3ff; border-radius:6px;"
        "color:#22d3ff; font-weight:bold; font-size:12px; letter-spacing:1px;}"
        "QPushButton:hover{background:#10364a;}"
    )
    lay.addWidget(btn)
    status = QLabel("... cargando movil ...")
    status.setWordWrap(True)
    status.setStyleSheet("color:#ff9a1f; font-size:11px;")
    lay.addWidget(status)
    helper.setCentralWidget(hw)
    helper.show()

    # state guarda datos temporales del ciclo de vinculacion:
    #   phase 0 -> primera carga (hay que arreglar localStorage)
    #   phase 1 -> pagina recargada (hay que leer estado)
    #   phase 2 -> ya esta corriendo normal
    #   did     -> deviceId que guardo el movil en localStorage
    #   sent    -> evita mostrar el pendiente varias veces
    #   paired  -> True cuando localStorage ya contiene token
    state = {"phase": 0, "did": None, "paired": None, "sent": False}

    def set_status(txt, ok=None):
        # Actualiza el texto y el color de la ventana auxiliar.
        # True=verde, False=rojo, None=naranja (pendiente).
        color = "#2dffb0" if ok is True else ("#ff3b5c" if ok is False else "#ff9a1f")
        status.setStyleSheet("color:%s; font-size:11px;" % color)
        status.setText(txt)

    def _read_state():
        # Ejecuta JavaScript dentro del movil y lee:
        #   - deviceId actual
        #   - si hay token de vinculacion (c.token)
        # Esto permite que el boton sepa si ya esta vinculado sin pedirlo
        # al servidor ni hacer que el usuario haga nada.
        js = (
            "(function(){try{var c=JSON.parse(localStorage.getItem('bioaccess_mobile_cfg_v2')||'{}');"
            "return JSON.stringify({d:c.deviceId||'',t:!!c.token});}catch(e){return '{}'}})()"
        )

        def cb(res):
            # QtWebEngine devuelve el resultado como string. Se convierte
            # a JSON; si algo falla, se deja un diccionario vacio para no
            # reventar el puntero auxiliar.
            try:
                o = json.loads(res or "{}")
            except Exception:
                o = {}
            state["did"] = o.get("d") or state["did"]
            paired = bool(o.get("t"))
            state["paired"] = paired
            if paired:
                state["sent"] = False
                set_status("VINCULADO - la PC ya puede pedir la huella.", True)
            elif not state["sent"]:
                set_status("Sin vincular - pulsa VINCULAR.", None)

        view.page().runJavaScript(js, cb)

    def _on_load_finished(ok):
        # Fase 0: en la PRIMERA carga se arregla localStorage para que el
        # movil apunte a 127.0.0.1:<puerto de esta PC>. Sin esto, el celular
        # simulado podria conservar una IP vieja (otro PC o <IP-DE-TU-PC>).
        # Fase 1: tras recargar, ya se lee el estado real de vinculacion.
        if state["phase"] == 0:
            # fijar la PC del movil a 127.0.0.1:<puerto> (misma sesion)
            state["phase"] = 1
            fix = (
                "(function(){try{var k='bioaccess_mobile_cfg_v2';"
                "var c=JSON.parse(localStorage.getItem(k)||'{}');"
                "c.ip='127.0.0.1';c.port='%d';"
                "localStorage.setItem(k,JSON.stringify(c));return 'ok';}"
                "catch(e){return String(e);}})()" % port
            )

            def _done(_):
                view.reload()

            view.page().runJavaScript(fix, _done)
        elif state["phase"] == 1:
            state["phase"] = 2
            _read_state()

    view.loadFinished.connect(_on_load_finished)
    view.setUrl(QUrl("http://127.0.0.1:%d/mobile/index.html" % port))
    mob.show()

    def _pair():
        # Boton VINCULAR:
        #   1) recupera el deviceId del movil;
        #   2) pide un codigo nuevo al servidor (pair_code(refresh=True));
        #   3) llama /api/pair/verify con ese codigo;
        #   4) la PC recibe la solicitud y muestra VINCULAR NUEVO CELULAR.
        did = state.get("did")
        if not did:
            set_status("Espera a que cargue el movil...", False)
            return
        try:
            import bioaccess_server as bs
            code = bs.pair_code(refresh=True)
            url = (
                base + "/api/pair/verify?code=" + urllib.parse.quote(code)
                + "&device=" + urllib.parse.quote("Navegador")
                + "&device_id=" + urllib.parse.quote(did)
            )
            with urllib.request.urlopen(url, timeout=5) as r:
                data = json.loads(r.read().decode())
            if data.get("ok"):
                state["sent"] = True
                set_status(
                    "SOLICITUD ENVIADA.\n"
                    "En la PC se abre 'VINCULAR NUEVO CELULAR'\n"
                    "-> pulsa ACEPTAR.  Codigo: " + code,
                    True,
                )
            else:
                set_status("Error del servidor: " + str(data.get("reason")), False)
        except Exception as e:
            set_status("Error: %s" % e, False)

    btn.clicked.connect(_pair)

    # Poll de estado: cada 1.5 segundos revisa si el movil ya tiene token.
    # Asi el color de la ventana auxiliar cambia de pendiente a VINCULADO
    # automaticamente despues de pulsar ACEPTAR en la PC.
    poll = QTimer()
    poll.timeout.connect(_read_state)
    poll.start(1500)

    def _quit():
        # Al cerrar la ventana PC, se apaga el servidor embebido y se termina
        # la aplicacion. Sin esto, el proceso podria quedar escuchando en
        # 127.0.0.1:8080 aunque ya cierres las ventanas.
        try:
            if getattr(pc, "server", None):
                pc.server.stop()
        except Exception:
            pass
        app.quit()

    # Cuando se destruye la ventana PC, se despide ordenadamente el proceso.
    pc.destroyed.connect(_quit)
    sys.exit(app.exec())

# Punto de entrada estandar de Python.
# Sin este if, importar el archivo (por ejemplo desde otro script) ejecutaria
# las ventanas automaticamente. Con el if, solo corre al ejecutarlo directo.
if __name__ == "__main__":
    main()
